import java.sql.*;

public class SecureExample {
    public void getUserData(String userId) throws SQLException {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/db", "user", "pass");

        // FIXED: Using PreparedStatement to prevent SQL Injection.
        // The '?' acts as a placeholder, ensuring input is treated only as data.
        String query = "SELECT * FROM users WHERE id = ?";
        PreparedStatement pstmt = conn.prepareStatement(query);

        // The driver automatically handles escaping of the input.
        pstmt.setString(1, userId);

        ResultSet rs = pstmt.executeQuery();

        while (rs.next()) {
            System.out.println("User: " + rs.getString("username"));
        }
    }
}
